impl ValueChecker for Match {
    fn check_match(&self, payload: &Value) -> bool {
        match self {
            Match::Value(MatchValue { value }) => match (payload, value) {
                (Value::String(stored), ValueVariants::String(val)) => stored == val,
                _ => false,
            },
            // ... other match variants
        }
    }
}

